-- Seed: Class economy actions (UI Actions tab)
-- Catálogo SSOT com C010 (painel). Recursos mago: C014.

INSERT INTO rpg.phb_class_economy_action (
  action_id, class_id, subclass_id, name, economy, unlock_level,
  resource_slug, free_resource_slug, always_spends_resource,
  summary, description, table_action, spend_amount, sort_order
) VALUES
('fighter-second-wind', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), NULL, 'Recuperar Fôlego', 'bonus'::rpg.action_economy_bucket, 1, 'secondWind', NULL, false, 'Cura 1d10 + nível de Guerreiro', 'Como Ação Bônus, você pode recuperar pontos de vida iguais a 1d10 + seu nível de Guerreiro. Você tem um número limitado de usos; recupere-os ao terminar um Descanso Curto ou Longo.', 'second-wind', NULL, 1),
('fighter-action-surge', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), NULL, 'Surto de Ação', 'action'::rpg.action_economy_bucket, 2, 'actionSurge', NULL, false, 'Concede uma ação adicional neste turno', 'No seu turno, você pode se esforçar além do normal e ganhar uma Ação adicional. Depois de usar Surto de Ação, você precisa terminar um Descanso Curto ou Longo para usá-lo de novo (em níveis altos, pode ter mais usos).', 'action-surge', NULL, 2),
('fighter-tactical-mind', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), NULL, 'Mente Tática', 'free'::rpg.action_economy_bucket, 2, 'secondWind', NULL, false, 'Ao falhar em teste: +1d10 (gasta Fôlego só se virar sucesso)', 'Quando você falha em um teste de habilidade, você pode gastar um uso de Recuperar Fôlego para rolar 1d10 e somar ao resultado. Se o teste ainda falhar, o uso de Recuperar Fôlego não é gasto.', 'tactical-mind', NULL, 3),
('fighter-indomitable', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), NULL, 'Indomável', 'free'::rpg.action_economy_bucket, 9, 'indomitable', NULL, false, 'Ao falhar salvaguarda: rerrola com +nível', 'Se você falhar em uma salvaguarda, pode rerrolá-la com um bônus igual ao seu nível de Guerreiro. Você deve usar o novo resultado. Usos limitados; recupere-os ao terminar um Descanso Longo. Na ficha, marque a opção Indomável ao rolar a salvaguarda.', NULL, NULL, 4),
('fighter-psi-protective-field', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Campo Protetor', 'reaction'::rpg.action_economy_bucket, 3, 'psi-energy-dice', NULL, true, 'Reação: reduz dano com 1 dado psi + INT', 'Quando você ou uma criatura que você possa ver a até 9 metros sofrer dano, use sua Reação e gaste um Dado de Energia Psiônica: reduza o dano pelo resultado do dado + seu modificador de Inteligência. Sempre gasta um dado (não tem uso gratuito).', 'psi:protective-field', NULL, 5),
('fighter-psi-telekinetic-movement', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Movimento Telecinético', 'action'::rpg.action_economy_bucket, 3, 'psi-energy-dice', 'telekinetic-movement', false, '1× gratuito por descanso; depois gasta 1 dado psi', 'Mova um objeto solto ou uma criatura voluntária conforme a característica. O primeiro uso após um Descanso Curto ou Longo é gratuito; usos extras gastam um Dado de Energia Psiônica.', 'psi:telekinetic-movement', NULL, 6),
('fighter-psi-psychic-leap', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Salto com Impulsão Psíquica', 'bonus'::rpg.action_economy_bucket, 7, 'psi-energy-dice', 'psychic-leap', false, '1× gratuito por descanso; voo = 2× deslocamento', 'Como Ação Bônus, você ganha Deslocamento de Voo igual ao dobro do seu Deslocamento até o fim do turno. O primeiro uso após um Descanso Curto ou Longo é gratuito; depois, gaste um Dado de Energia Psiônica.', 'psi:psychic-leap', NULL, 7),
('fighter-psi-mental-guard', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Resguardo Mental', 'free'::rpg.action_economy_bucket, 10, 'psi-energy-dice', NULL, true, 'Gasta 1 dado: encerra Amedrontado/Enfeitiçado', 'Gaste um Dado de Energia Psiônica (nenhuma ação) para encerrar em você todos os efeitos que causam as condições Amedrontado ou Enfeitiçado. Sempre gasta um dado.', 'psi:mental-guard', NULL, 8),
('fighter-psi-energy-bulwark', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Baluarte de Energia', 'bonus'::rpg.action_economy_bucket, 15, 'psi-energy-dice', 'energy-bulwark', false, '1× gratuito por descanso longo; Cobertura Parcial', 'Conceda Cobertura Parcial por 1 minuto a até o seu modificador de Inteligência em criaturas (mínimo 1). O primeiro uso após um Descanso Longo é gratuito; depois, gaste um Dado de Energia Psiônica.', 'psi:energy-bulwark', NULL, 9),
('fighter-psi-telekinetic-master', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'psi-warrior'), 'Mestre Telecinético', 'free'::rpg.action_economy_bucket, 18, 'psi-energy-dice', 'telekinetic-master', false, '1× gratuito por descanso longo; Telecinese', 'Conjure Telecinese sem espaço nem componentes (INT é o atributo). O primeiro uso após um Descanso Longo é gratuito; depois, gaste um Dado de Energia Psiônica.', 'psi:telekinetic-master', NULL, 10),
('fighter-bm-lunging-attack', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'battle-master'), 'Ataque Estendido', 'bonus'::rpg.action_economy_bucket, 3, 'superiority-dice', NULL, false, 'Manobra: Correr e potencializar ataque', 'Manobra do Mestre de Batalha. Gaste um dado de superioridade para potencializar um ataque com alcance ou movimento extra conforme a manobra escolhida (veja o texto completo da manobra na aba de poderes).', NULL, NULL, 11),
('fighter-bm-rally', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'battle-master'), 'Reunir', 'bonus'::rpg.action_economy_bucket, 3, 'superiority-dice', NULL, false, 'Manobra: PV temporários a um aliado', 'Como Ação Bônus, gaste um dado de superioridade para conceder pontos de vida temporários a um aliado. O aliado ganha PV temporários iguais ao resultado do dado + seu modificador de Carisma.', NULL, NULL, 12),
('fighter-bm-feinting-attack', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'battle-master'), 'Ataque Fintado', 'bonus'::rpg.action_economy_bucket, 3, 'superiority-dice', NULL, false, 'Manobra: Vantagem no próximo ataque', 'Como Ação Bônus, gaste um dado de superioridade para fintar: você ganha Vantagem no próximo ataque contra o alvo neste turno e adiciona o dado ao dano se acertar.', NULL, NULL, 13),
('fighter-bm-parry', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'battle-master'), 'Aparar', 'reaction'::rpg.action_economy_bucket, 3, 'superiority-dice', NULL, false, 'Manobra: reduzir dano corpo a corpo', 'Quando você é atingido por um ataque corpo a corpo, use sua Reação e gaste um dado de superioridade para reduzir o dano sofrido pelo resultado do dado + seu modificador de Destreza.', NULL, NULL, 14),
('fighter-bm-riposte', (SELECT id FROM rpg.phb_class WHERE slug = 'fighter'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'battle-master'), 'Repostagem', 'reaction'::rpg.action_economy_bucket, 3, 'superiority-dice', NULL, false, 'Manobra: contra-ataque ao ser errado', 'Quando uma criatura erra um ataque corpo a corpo contra você, use sua Reação para gastar um dado de superioridade e fazer um ataque com arma contra ela, adicionando o dado ao dano se acertar.', NULL, NULL, 15),
('rogue-cunning-action', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), NULL, 'Ação Ardilosa', 'bonus'::rpg.action_economy_bucket, 2, NULL, NULL, false, 'Correr, Desengajar ou Esconder', NULL, NULL, NULL, 16),
('rogue-uncanny-dodge', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), NULL, 'Esquiva Sobrenatural', 'reaction'::rpg.action_economy_bucket, 5, NULL, NULL, false, 'Metade do dano de um ataque que o acertou', NULL, NULL, NULL, 17),
('rogue-soulknife-second-blade', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Segunda Lâmina Psíquica', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Ação Bônus: card Lâmina Psíquica (adicional) na ficha', 'Use o card de ataque Lâmina Psíquica (adicional) na aba Ações — 1d4 Psíquico, com Furtivo/Golpe Astuto.', NULL, NULL, 18),
('rogue-soulknife-psi-dice', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Poder Psiônico', 'free'::rpg.action_economy_bucket, 3, 'soulknife-psi-dice', NULL, false, 'Pool de Dados de Energia (Adaga Espiritual)', 'Controle do pool de dados psiônicos na mesa. Gastos vêm das ações Soulknife (Sussurros, Teleporte, Véu, Rasgar Mente, Aptidão, Golpe Teleguiado).', NULL, NULL, 19),
('rogue-psychic-whispers', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Sussurros Psíquicos', 'action'::rpg.action_economy_bucket, 3, 'psychic-whispers', NULL, false, 'Listagem: 1× gratuito / DL (depois dado psi no painel)', 'Aparece na Economia/painel para gastar o uso. Duração da ligação = nota na mesa (sem tracker).', 'psychic-whispers', NULL, 20),
('rogue-psychic-teleportation', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Teleporte Psíquico', 'bonus'::rpg.action_economy_bucket, 9, 'soulknife-psi-dice', NULL, true, 'Teleporte gastando 1 dado psiônico', 'Como Ação Bônus, gaste 1 Dado de Energia: teleporte até (resultado × 3) m para um espaço visível e desocupado.', 'psychic-teleport', NULL, 21),
('rogue-psychic-veil', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Véu Psíquico', 'action'::rpg.action_economy_bucket, 13, 'psychic-veil', NULL, false, '1× gratuito / DL (uso pré-estabelecido; depois 1 dado psi)', 'Uso gratuito no pool psychic-veil; gaste no Usar/painel. Invisível até 1 h = nota na mesa (sem tracker de duração).', 'psychic-veil', NULL, 22),
('rogue-rend-mind', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'soulknife'), 'Rasgar Mente', 'free'::rpg.action_economy_bucket, 17, 'rend-mind', NULL, false, 'Listagem: 1× gratuito (depois 3 dados psi no painel)', 'Aparece na Economia/painel para gastar o uso. Atordoado no alvo = nota/salvaguarda na mesa.', 'rend-mind', NULL, 23),
('rogue-spell-thief', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'arcane-trickster'), 'Ladrão de Magias', 'reaction'::rpg.action_economy_bucket, 17, 'spell-thief', NULL, true, 'Negar e roubar uma magia', 'Como Reação, gaste o uso para negar e roubar uma magia (mesa).', 'spell-thief', NULL, 24),
('rogue-arachnoid-web', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'arachnoid-stalker'), 'Correia / Teia', 'bonus'::rpg.action_economy_bucket, 3, 'arachnoid-web', NULL, true, 'Teias para movimento, objetos, corda ou magia Teia', 'Gaste 1 uso de Correia Aracnóide para criar teia/correia (mesa: posição e condição).', 'arachnoid-web', NULL, 25),
('rogue-stroke-of-luck', (SELECT id FROM rpg.phb_class WHERE slug = 'rogue'), NULL, 'Golpe de Sorte', 'free'::rpg.action_economy_bucket, 20, 'strokeOfLuck', NULL, false, 'Transforma falha em 20 (1×/DL)', 'Ao falhar em um Teste de D20, transforme o resultado em 20. Marque o gasto na rolagem (ataque, perícia, iniciativa, salvaguarda). Contador na Economia.', NULL, NULL, 26),
('barbarian-rage', (SELECT id FROM rpg.phb_class WHERE slug = 'barbarian'), NULL, 'Fúria', 'bonus'::rpg.action_economy_bucket, 1, 'rage', NULL, false, 'Entrar em Fúria', NULL, NULL, NULL, 21),
('barbarian-reckless', (SELECT id FROM rpg.phb_class WHERE slug = 'barbarian'), NULL, 'Ataque Imprudente', 'free'::rpg.action_economy_bucket, 2, NULL, NULL, false, 'No seu turno, ao atacar: Vantagem (e ataques contra você também)', NULL, NULL, NULL, 22),
('monk-flurry', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Torrente de Golpes', 'bonus'::rpg.action_economy_bucket, 2, 'focusPoints', NULL, false, 'Dois ataques desarmados (gasta Foco)', NULL, NULL, NULL, 23),
('monk-patient-defense', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Defesa Paciente', 'bonus'::rpg.action_economy_bucket, 2, 'focusPoints', NULL, false, 'Esquivar (gasta Foco)', NULL, NULL, NULL, 24),
('monk-step-of-the-wind', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Passos do Vento', 'bonus'::rpg.action_economy_bucket, 2, 'focusPoints', NULL, false, 'Correr ou Desengajar; salto dobrado (gasta Foco)', NULL, NULL, NULL, 25),
('monk-stunning-strike', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Golpe Atordoante', 'free'::rpg.action_economy_bucket, 5, 'focusPoints', NULL, false, 'Ao acertar: tentativa de Atordoar (gasta Foco)', NULL, NULL, NULL, 26),
('monk-deflect', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Defletir Ataques', 'reaction'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Reduz dano de ataque corpo a corpo ou à distância', NULL, NULL, NULL, 27),
('monk-slow-fall', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), NULL, 'Queda Lenta', 'reaction'::rpg.action_economy_bucket, 4, NULL, NULL, false, 'Reduz dano de queda', NULL, NULL, NULL, 28),
('monk-hand-of-healing', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'mercy'), 'Mão de Cura', 'action'::rpg.action_economy_bucket, 3, 'focusPoints', NULL, false, 'Cura com Foco', NULL, NULL, NULL, 29),
('monk-shadow-step', (SELECT id FROM rpg.phb_class WHERE slug = 'monk'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'shadow'), 'Passo da Sombra', 'bonus'::rpg.action_economy_bucket, 6, NULL, NULL, false, 'Teleporte entre sombras', NULL, NULL, NULL, 30),
('bard-inspiration', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), NULL, 'Inspiração de Bardo', 'bonus'::rpg.action_economy_bucket, 1, 'bardicInspiration', NULL, false, 'Conceder o dado a um aliado a até 18 m', NULL, NULL, NULL, 31),
('bard-cutting-words', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'lore'), 'Palavras de Interrupção', 'reaction'::rpg.action_economy_bucket, 3, 'bardicInspiration', NULL, false, 'Subtrair o dado de ataque/teste/dano inimigo', NULL, NULL, NULL, 32),
('bard-agile-response', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'dance'), 'Movimento Inspirador', 'reaction'::rpg.action_economy_bucket, 6, 'bardicInspiration', NULL, false, 'Reação: mover metade do Deslocamento (você + aliado)', NULL, NULL, NULL, 33),
('bard-combat-inspiration', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'valor'), 'Inspiração em Combate', 'reaction'::rpg.action_economy_bucket, 3, 'bardicInspiration', NULL, false, 'Aliado soma o dado ao dano ou à CA', NULL, NULL, NULL, 34),
('bard-mantle-of-majesty', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glamour'), 'Manto de Majestade', 'bonus'::rpg.action_economy_bucket, 6, NULL, NULL, false, 'Conjurar Comando sem gastar espaço', NULL, NULL, NULL, 35),
('bard-virtuoso-skill', (SELECT id FROM rpg.phb_class WHERE slug = 'bard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'college-of-masks'), 'Habilidade de Virtuoso', 'free'::rpg.action_economy_bucket, 6, 'virtuoso-skill', NULL, true, '1×/turno: Teste d20 com Carisma', 'Uma vez por turno, ao fazer um Teste d20, você pode fazê-lo com Carisma se ainda não usar. Gaste 1 uso (máx. = mod. de Carisma).', 'spend-resource', NULL, 36),
('paladin-lay-on-hands', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), NULL, 'Mãos Consagradas', 'bonus'::rpg.action_economy_bucket, 1, 'layOnHands', NULL, false, 'Cura da reserva (5 × nível)', 'Como Ação Bônus, toque uma criatura e gaste pontos da reserva de Mãos Consagradas para restaurar essa quantidade de PV. A reserva máxima é 5 × seu nível de Paladino; recupere todos os pontos ao terminar um Descanso Longo. Use o painel do Paladino para escolher a quantidade.', 'lay-on-hands', NULL, 37),
('paladin-channel', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), NULL, 'Canalizar Divindade', 'free'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, false, 'Pool de Canalizar Divindade', 'Controle ± dos usos de Canalizar Divindade. Gastos vêm de Sentido Divino, opções do Juramento e Repudiar Inimigos. Recupere 1 uso num Descanso Curto e todos num Descanso Longo (mais usos em níveis altos).', NULL, NULL, 38),
('paladin-divine-sense', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), NULL, 'Sentido Divino', 'bonus'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Detectar celestiais, ínferos e mortos-vivos', 'Como Ação Bônus, gaste 1 uso de Canalizar Divindade. Por até 10 minutos, você sente a localização de qualquer Celestial, Ínfero ou Morto-Vivo a até 18 m que não esteja sob Cobertura Total, e locais/objetos consagrados ou profanados (como Hallow).', 'divine-sense', NULL, 39),
('paladin-sacred-weapon', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'devotion'), 'Arma Sagrada', 'free'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Na ação Atacar: +Carisma e luz', 'Ao executar a ação Atacar, gaste 1 Canalizar Divindade para imbuir uma arma corpo a corpo que você empunha. Por 10 minutos (ou até usar de novo / largar a arma): some o mod. de Carisma (mín. +1) às jogadas de ataque com ela; nos acertos, o dano pode ser do tipo normal ou Radiante; emite Luz Plena em 6 m e Luz Fraca em +6 m. Você pode encerrar o efeito sem ação.', 'oath-channel', NULL, 40),
('paladin-aura-of-devotion', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'devotion'), 'Aura de Devoção', 'free'::rpg.action_economy_bucket, 7, NULL, NULL, false, 'Imunidade a Enfeitiçado na aura', 'Você e aliados têm Imunidade à condição Enfeitiçado enquanto estiverem em sua Aura de Proteção. Se um aliado Enfeitiçado entrar na aura, a condição não tem efeito enquanto ele permanecer nela.', NULL, NULL, 41),
('paladin-protective-smite', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'devotion'), 'Destruição Protetora', 'free'::rpg.action_economy_bucket, 15, NULL, NULL, false, 'Destruição Divina → Cobertura Parcial na aura', 'Ao conjurar Destruição Divina, você e seus aliados têm Cobertura Parcial enquanto estiverem em sua Aura de Proteção. A aura mantém este benefício até o início do seu próximo turno.', NULL, NULL, 42),
('paladin-holy-nimbus', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'devotion'), 'Resplendor Sagrado', 'bonus'::rpg.action_economy_bucket, 20, 'holy-nimbus', NULL, true, 'Aura sagrada por 10 min (1×/DL)', 'Como Ação Bônus, imbuir a Aura de Proteção por 10 minutos (ou até encerrar). 1×/Descanso Longo (ou gaste um espaço de 5º). Inimigos que iniciam o turno na aura sofrem dano Radiante igual ao mod. de Carisma + PB; a aura tem Luz Plena (luz solar); Vantagem em salvaguardas forçadas por Ínferos ou Mortos-Vivos.', 'spend-resource', NULL, 43),
('paladin-inspiring-smite', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glory'), 'Destruição Inspiradora', 'bonus'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Após Destruição Divina: rola PV temp', 'Imediatamente após conjurar Destruição Divina, gaste 1 Canalizar Divindade. Role 2d8 + seu nível de Paladino e distribua esses PV temporários entre você e criaturas a até 9 m. O Usar rola o total e aplica na ficha (ajuste se dividir na mesa).', 'inspiring-smite', NULL, 44),
('paladin-peerless-athlete', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glory'), 'Atleta Inigualável', 'bonus'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Vantagem em Atletismo/Acrobacia (1 h)', 'Como Ação Bônus, gaste 1 Canalizar Divindade. Por 1 hora: Vantagem em testes de Força (Atletismo) e Destreza (Acrobacia); Saltos Longos e em Altura aumentam em 3 m (custa movimento normal).', 'peerless-athlete', NULL, 45),
('paladin-aura-of-alacrity', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glory'), 'Aura de Vivacidade', 'free'::rpg.action_economy_bucket, 7, NULL, NULL, false, '+3 m de deslocamento (você e aura)', 'Seu Deslocamento aumenta em 3 m. Além disso, quando um aliado entra na Aura de Proteção pela 1ª vez num turno ou inicia o turno nela, o Deslocamento dele aumenta em 3 m até o fim do próximo turno dele.', NULL, NULL, 46),
('paladin-glorious-defense', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glory'), 'Defesa Gloriosa', 'reaction'::rpg.action_economy_bucket, 15, 'glorious-defense', NULL, false, 'Reação: +CA (Carisma) e possível contra-ataque', 'Quando você ou outra criatura à sua vista a até 3 m é atingida por uma jogada de ataque, use a Reação e gaste 1 uso: conceda bônus à CA do alvo contra esse ataque igual ao seu mod. de Carisma (mín. +1), podendo fazer o ataque errar. Se errar e o atacante estiver no alcance da sua arma, você pode atacar com uma arma como parte desta Reação. Usos = mod. de Carisma (mín. 1)/Descanso Longo — marque no contador ±.', NULL, NULL, 47),
('paladin-living-legend', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'glory'), 'Lenda Viva', 'bonus'::rpg.action_economy_bucket, 20, 'living-legend', NULL, true, 'Presença lendária por 10 min (1×/DL)', 'Como Ação Bônus, receba os benefícios por 10 minutos. 1×/Descanso Longo (ou gaste um espaço de 5º). Carismático: Vantagem em testes de Carisma. Golpe Infalível: 1×/seu turno, ao errar ataque com arma, transforme em acerto. Jogar Novamente a Salvaguarda: se falhar numa salvaguarda, Reação para rerrolar (use o novo resultado).', 'spend-resource', NULL, 48),
('paladin-natures-wrath', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'ancients'), 'A Ira da Natureza', 'action'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Canalizar: videiras Contêm (4,5 m)', 'Como ação Usar Magia, gaste 1 Canalizar Divindade. Cada criatura à sua escolha que você possa ver a até 4,5 m deve passar numa salvaguarda de Força ou fica Contida por 1 minuto. A criatura Contida repete a salvaguarda no fim de cada turno dela, encerrando o efeito em sucesso.', 'oath-channel', NULL, 49),
('paladin-aura-of-warding', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'ancients'), 'Aura de Resistência', 'free'::rpg.action_economy_bucket, 7, NULL, NULL, false, 'Resistência a Necrótico, Psíquico e Radiante', 'Você e aliados têm Resistência a dano Necrótico, Psíquico e Radiante enquanto estiverem em sua Aura de Proteção.', NULL, NULL, 50),
('paladin-undying-sentinel', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'ancients'), 'Sentinela Imortal', 'free'::rpg.action_economy_bucket, 15, 'undying-sentinel', NULL, false, 'A 0 PV: fica com 1 + cura (3× nível)', 'Ao ser reduzido a 0 PV e não morto imediatamente, você fica com 1 PV e recupera PV iguais a 3 × seu nível de Paladino. 1×/Descanso Longo (contador ±). Você também não envelhece magicamente.', NULL, NULL, 51),
('paladin-elder-champion', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'ancients'), 'Campeão Ancestral', 'bonus'::rpg.action_economy_bucket, 20, 'elder-champion', NULL, true, 'Aura ancestral por 1 min (1×/DL)', 'Como Ação Bônus, imbuir a Aura de Proteção por 1 minuto. 1×/Descanso Longo (ou espaço de 5º). Inimigos na aura têm Desvantagem em salvaguardas contra suas magias e Canalizar Divindade; magias de ação podem ser conjuradas como Ação Bônus; no início de cada turno você recupera 10 PV.', 'spend-resource', NULL, 52),
('paladin-vow-of-enmity', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'vengeance'), 'Voto de Inimizade', 'free'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Na ação Atacar: Vantagem vs 1 alvo', 'Ao executar a ação Atacar, gaste 1 Canalizar Divindade e escolha uma criatura à vista a até 9 m. Você tem Vantagem nas jogadas de ataque contra ela por 1 minuto ou até usar de novo. Se ela cair a 0 PV antes do fim, você pode transferir o voto a outra criatura a até 9 m (sem ação).', 'oath-channel', NULL, 53),
('paladin-relentless-avenger', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'vengeance'), 'Vingador Implacável', 'free'::rpg.action_economy_bucket, 7, NULL, NULL, false, 'Ao acertar AO: Desloc. 0 + metade do movimento', 'Ao atingir uma criatura com um Ataque de Oportunidade, você pode reduzir o Deslocamento dela a 0 até o fim do turno atual e então se mover até metade do seu Deslocamento como parte da mesma Reação. Esse movimento não provoca Ataques de Oportunidade.', NULL, NULL, 54),
('paladin-soul-of-vengeance', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'vengeance'), 'Alma Vingativa', 'reaction'::rpg.action_economy_bucket, 15, NULL, NULL, false, 'Reação: ataque vs alvo do Voto', 'Imediatamente após uma criatura sob seu Voto de Inimizade acertar ou errar com uma jogada de ataque, você pode usar a Reação para realizar um ataque corpo a corpo contra ela se estiver ao seu alcance.', NULL, NULL, 55),
('paladin-avenging-angel', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'vengeance'), 'Anjo Vingador', 'bonus'::rpg.action_economy_bucket, 20, 'avenging-angel', NULL, true, 'Voo + aura Amedrontar (10 min)', 'Como Ação Bônus, benefícios por 10 minutos. 1×/Descanso Longo (ou espaço de 5º). Inimigos que iniciam o turno na Aura de Proteção: salvaguarda de Sabedoria ou Amedrontado por 1 min (ou até sofrer dano); ataques contra Amedrontados têm Vantagem. Você ganha Deslocamento de Voo de 18 m e pode pairar.', 'spend-resource', NULL, 56),
('paladin-conjure-beverage', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'oath-of-revelry'), 'Conjurar Bebida', 'action'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Canalizar: canecas com PV temp e Vantagem', 'Como Ação Mágica, gaste 1 Canalizar Divindade para conjurar até o seu mod. de Carisma (mín. 1) canecas de cerveja a até 9 m. Beber como Ação Bônus: PV temporários iguais ao mod. de Carisma e Vantagem em salvaguardas por 1 minuto. Canecas restantes desaparecem ao terminar um Descanso Longo.', 'oath-channel', NULL, 57),
('paladin-aura-of-fellowship', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'oath-of-revelry'), 'Aura de Fraternidade', 'free'::rpg.action_economy_bucket, 7, NULL, NULL, false, '+1d4 dano corpo a corpo na aura', 'Você e aliados causam +1d4 de dano extra em ataques com armas corpo a corpo ou Ataques Desarmados enquanto estiverem na Aura de Proteção. O tipo do dano extra é o mesmo do ataque.', NULL, NULL, 58),
('paladin-reveler', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'oath-of-revelry'), 'Folião', 'reaction'::rpg.action_economy_bucket, 15, 'reveler', NULL, false, 'Reação: Vantagem em Teste d20 (aliado 9 m)', 'Quando você ou um aliado a até 9 m que possa ver ou ouvir você faz um Teste de D20, use a Reação para conceder Vantagem nesse teste. Usos = mod. de Carisma (mín. 1)/Descanso Longo. Se a criatura ainda falhar, este uso não é gasto — marque no contador ±.', NULL, NULL, 59),
('paladin-party-animal', (SELECT id FROM rpg.phb_class WHERE slug = 'paladin'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'oath-of-revelry'), 'Animal de Festa', 'bonus'::rpg.action_economy_bucket, 20, 'party-animal', NULL, true, 'Aura festiva por 10 min (1×/DL)', 'Como Ação Bônus, imbuir a Aura de Proteção por 10 minutos. 1×/Descanso Longo (ou espaço de 5º). Dano da Aura de Fraternidade vira 1d8; no início de cada turno você pode dar Inspiração Heroica a um aliado na aura; imunidade a Cego, Surdo, Exaustão e Envenenado na aura.', 'spend-resource', NULL, 60),
('ranger-hunters-mark', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), NULL, 'Marca do Predador', 'bonus'::rpg.action_economy_bucket, 1, 'favoredEnemy', NULL, false, 'Marcar alvo (uso gratuito disponível)', 'Como Ação Bônus, gaste 1 uso de Inimigo Favorito para conjurar Marca do Predador sem espaço (concentração).', 'hunters-mark-free', NULL, 41),
('ranger-tireless', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), NULL, 'Incansável', 'action'::rpg.action_economy_bucket, 10, 'tireless', NULL, true, 'Ação: PV temporários 1d8 + SAB', 'Como ação, gaste 1 uso para ganhar PV temporários iguais a 1d8 + seu modificador de Sabedoria.', 'tireless', NULL, 40),
('ranger-natures-veil', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), NULL, 'Véu da Natureza', 'bonus'::rpg.action_economy_bucket, 14, 'naturesVeil', NULL, true, 'Tornar-se Invisível até o fim do próximo turno', 'Como Ação Bônus, gaste 1 uso para ficar Invisível até o fim do seu próximo turno.', 'natures-veil', NULL, 42),
('ranger-primal-companion', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'beast-master'), 'Companheiro Primal', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Comandar a fera', 'Ação Bônus: comande a fera; na ação Atacar você pode sacrificar um ataque para o Golpe da Fera (mesa).', 'primal-companion', NULL, 43),
('ranger-hunter-defense', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'hunter'), 'Defesa do Caçador Superior', 'reaction'::rpg.action_economy_bucket, 15, NULL, NULL, false, 'Resistência ao dano neste turno', 'Quando sofrer dano, use a Reação para ganhar Resistência a esse dano até o fim do turno atual (mesa).', 'hunter-defense', NULL, 44),
('ranger-gloom-stalker-dodge', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'gloom-stalker'), 'Esquiva Sombria', 'reaction'::rpg.action_economy_bucket, 15, NULL, NULL, false, 'Desvantagem no ataque e teleporte de 9 m', 'Quando um atacante que você possa ver erra ou está prestes a acertar: imponha Desvantagem e teleporte até 9 m (mesa).', 'gloom-stalker-dodge', NULL, 45),
