('ranger-beastborne-aspect', (SELECT id FROM rpg.phb_class WHERE slug = 'ranger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'beastborne'), 'Aspecto Bestial (mesa)', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Tracker de Aspecto Bestial (0–5) na mesa', 'Ajuste o nível de Aspecto Bestial no painel do Patrulheiro (+/− ou Uivo Feral). Benefícios acumulam: Carnificina, Velocidade, Frenesi, Pele, Retaliação. Zera no descanso longo (e após 1 min sem dano na mesa).', NULL, NULL, 47),
