('cleric-dragon-majesty', (SELECT id FROM rpg.phb_class WHERE slug = 'cleric'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'dragon-domain'), 'Majestade Dracônica', 'action'::rpg.action_economy_bucket, 3, 'channelDivinity', NULL, true, 'Canalizar: Enfeitiçar ou Amedrontar (9 m)', 'Ação Mágica: apresente o Símbolo Sagrado e gaste Canalizar Divindade. Emanação de 9 m — Enfeitiçado ou Amedrontado (salvaguarda SAB, 1 min).', 'spend-resource', NULL, 51),
('cleric-legendary-aspect', (SELECT id FROM rpg.phb_class WHERE slug = 'cleric'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'dragon-domain'), 'Aspecto Lendário', 'free'::rpg.action_economy_bucket, 17, 'legendary-aspect', NULL, true, 'Ação lendária (Rasgar / Cauda / Asas)', 'Gaste 1 uso para Rasgar, Golpe de Cauda ou Batida de Asas imediatamente após o turno de outra criatura. 3 usos/LR.', 'spend-resource', NULL, 52),
