('druid-city-shape', (SELECT id FROM rpg.phb_class WHERE slug = 'druid'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'circle-of-the-city'), 'Forma da Cidade', 'bonus'::rpg.action_economy_bucket, 3, 'wildShape', NULL, true, 'Gaste Forma Selvagem: Fundir-se / Passagem / Moldar Rocha', 'Gaste 1 uso de Forma Selvagem para conjurar Fundir-se na Pedra, Passagem ou Moldar Rocha sem espaço de magia (mesa).', 'spend-resource', NULL, 56),
('druid-wall-warp', (SELECT id FROM rpg.phb_class WHERE slug = 'druid'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'circle-of-the-city'), 'Distorção de Muro', 'reaction'::rpg.action_economy_bucket, 10, 'wall-warp', NULL, true, 'Painel de Muralha de Pedra (1×/LR)', 'Reação: ao ver um ataque causar dano a até 18 m, gaste o uso para erguer um painel 3×3 m (CA 15, 30 PV) até o fim do seu próximo turno.', 'spend-resource', NULL, 57),
('sorcerer-innate-sorcery', (SELECT id FROM rpg.phb_class WHERE slug = 'sorcerer'), NULL, 'Feitiçaria Inata', 'bonus'::rpg.action_economy_bucket, 1, 'innate-sorcery', NULL, true, '+1 na CD e Vantagem em ataques de magia de Feiticeiro (1 min; 2×/DL)', 'Ação Bônus: libera a magia por 1 minuto. Sem usos (L7+): gaste 2 Pontos de Feitiçaria (Feitiçaria Encarnada).', 'innate-sorcery', NULL, 58),
