('sorcerer-restore-balance', (SELECT id FROM rpg.phb_class WHERE slug = 'sorcerer'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'clockwork'), 'Restaurar Equilíbrio', 'reaction'::rpg.action_economy_bucket, 3, 'restore-balance', NULL, true, 'Reação: cancela Vantagem/Desvantagem em d20 (usos = CAR)', 'Quando uma criatura à sua vista a até 18 m estiver prestes a jogar um d20 com Vantagem ou Desvantagem, use sua Reação para evitar que o teste seja afetado.', 'restore-balance', NULL, 78),
